 r.post('/api/store/classes/:id/push',async c=>{const[u,e]=await need(c);if(e)return e;const D=c.env.DB,cl=await CL(c,c.params.id);if(!cl||(cl.teacher_id!==u.id&&u.role!=='admin'))return J({error:'forbidden'},403);const id=+(await c.request.json()).item,it=await D.prepare("SELECT id,name,price_tzs,seller_id,license FROM store_items WHERE id=? AND status='published' AND kind='Files'").bind(id).first();if(!it)return J({error:'File not found'},404);const mine=await D.prepare('SELECT 1 x FROM store_library WHERE user_id=? AND item_id=?').bind(u.id,id).first();if(!(u.role==='admin'||it.price_tzs===0||it.seller_id===u.id||(mine&&/class|school/i.test(String(it.license)))))return J({error:'This file needs a Classroom or School license to share with a class'},403);await D.prepare('INSERT OR IGNORE INTO store_class_items(class_id,item_id) VALUES(?,?)').bind(cl.id,id).run();const mem=(await D.prepare('SELECT user_id FROM store_class_members WHERE class_id=? LIMIT 500').bind(cl.id).all()).results;for(const m of mem)await D.prepare(LIB).bind(m.user_id,id,id).run();c.ctx.waitUntil((async()=>{for(const m of mem)await notify(c.env,m.user_id,'class','New in '+cl.name,it.name,'/smart21store.html?item='+id)})());return J({ok:1,members:mem.length})});
 r.get('/api/store/classes/:id/report',async c=>{const[u,e]=await need(c);if(e)return e;const D=c.env.DB,cl=await CL(c,c.params.id);if(!cl||(cl.teacher_id!==u.id&&u.role!=='admin'))return J({error:'forbidden'},403);const items=(await D.prepare('SELECT i.id,i.name FROM store_class_items ci JOIN store_items i ON i.id=ci.item_id WHERE ci.class_id=?').bind(cl.id).all()).results,mem=(await D.prepare('SELECT m.user_id id,(SELECT name FROM users WHERE id=m.user_id) AS name FROM store_class_members m WHERE m.class_id=?').bind(cl.id).all()).results,pg=(await D.prepare('SELECT user_id,item_id,pct FROM store_progress WHERE user_id IN (SELECT user_id FROM store_class_members WHERE class_id=?1) AND item_id IN (SELECT item_id FROM store_class_items WHERE class_id=?1)').bind(cl.id).all()).results;for(const m of mem){m.p={};for(const x of pg)if(x.user_id===m.id)m.p[x.item_id]=x.pct}return J({name:cl.name,items,members:mem})});
 // shareable wishlist
 r.post('/api/store/lists/share',async c=>{const[u,e]=await need(c);if(e)return e;const D=c.env.DB,title=String((await c.request.json()).title||'').trim().slice(0,60)||'My wishlist';let x=await D.prepare('SELECT code FROM store_lists WHERE user_id=?').bind(u.id).first();if(x)await D.prepare('UPDATE store_lists SET title=? WHERE user_id=?').bind(title,u.id).run();else{const al='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let code='';for(const b of crypto.getRandomValues(new Uint8Array(8)))code+=al[b%al.length];await D.prepare('INSERT INTO store_lists(code,user_id,title) VALUES(?,?,?)').bind(code,u.id,title).run();x={code}}return J({code:x.code})});
 r.get('/api/store/list/:code',async({env,params})=>{const l=await env.DB.prepare('SELECT l.title,l.user_id,(SELECT name FROM users WHERE id=l.user_id) AS owner FROM store_lists l WHERE l.code=?').bind(String(params.code).toUpperCase()).first();if(!l)return J({error:'List not found'},404);const ids=(await env.DB.prepare("SELECT w.item_id FROM store_wishlist w JOIN store_items i ON i.id=w.item_id WHERE w.user_id=? AND i.status='published'").bind(l.user_id).all()).results.map(x=>x.item_id);return J({title:l.title,owner:String(l.owner||'').split(' ')[0],ids})});
 // rewards: idempotent ledger (install +10, review +20, referral +30, daily check-in +5 and streak bonus); redeem for one-time coupons
 const PT=async(c,u)=>{const D=c.env.DB;await D.prepare("INSERT OR IGNORE INTO store_points_log(user_id,reason,ref,pts) SELECT user_id,'install',CAST(item_id AS TEXT),10 FROM store_library WHERE user_id=?").bind(u.id).run();await D.prepare("INSERT OR IGNORE INTO store_points_log(user_id,reason,ref,pts) SELECT user_id,'review',CAST(id AS TEXT),20 FROM store_reviews WHERE user_id=?").bind(u.id).run();const rf=await D.prepare('SELECT code FROM store_referrals WHERE owner_id=?').bind(u.id).first();if(rf){const cp=await D.prepare('SELECT used FROM store_coupons WHERE code=?').bind(rf.code).first();for(let k=1;k<=Math.min(cp?.used||0,200);k++)await D.prepare("INSERT OR IGNORE INTO store_points_log(user_id,reason,ref,pts) VALUES(?,'refer',?,30)").bind(u.id,String(k)).run()}const bal=(await D.prepare('SELECT COALESCE(SUM(pts),0) n FROM store_points_log WHERE user_id=?').bind(u.id).first()).n,st=await D.prepare('SELECT last_day,streak FROM store_points_state WHERE user_id=?').bind(u.id).first(),today=new Date().toISOString().slice(0,10),log=(await D.prepare('SELECT reason,pts,created_at FROM store_points_log WHERE user_id=? ORDER BY id DESC LIMIT 15').bind(u.id).all()).results,y=new Date(Date.now()-864e5).toISOString().slice(0,10);return{balance:bal,streak:st&&(st.last_day===today||st.last_day===y)?st.streak:0,today:!!st&&st.last_day===today,log,referrals:rf?(await D.prepare('SELECT used FROM store_coupons WHERE code=?').bind(rf.code).first())?.used||0:0}};
 r.get('/api/store/points',async c=>{const[u,e]=await need(c);if(e)return e;return J(await PT(c,u))});
 r.post('/api/store/points/checkin',async c=>{const[u,e]=await need(c);if(e)return e;const D=c.env.DB,today=new Date().toISOString().slice(0,10),y=new Date(Date.now()-864e5).toISOString().slice(0,10),st=await D.prepare('SELECT last_day,streak FROM store_points_state WHERE user_id=?').bind(u.id).first();if(st&&st.last_day===today)return J(await PT(c,u));const sk=st&&st.last_day===y?st.streak+1:1;await D.prepare('INSERT INTO store_points_state(user_id,last_day,streak) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET last_day=?2,streak=?3').bind(u.id,today,sk).run();await D.prepare("INSERT OR IGNORE INTO store_points_log(user_id,reason,ref,pts) VALUES(?,'daily',?,?)").bind(u.id,today,5+Math.min(sk-1,6)).run();return J(await PT(c,u))});
 r.post('/api/store/points/redeem',async c=>{const[u,e]=await need(c);if(e)return e;const D=c.env.DB,tier={200:10,450:20,700:30}[+(await c.request.json()).cost];if(!tier)return J({error:'bad tier'},400);const p=await PT(c,u),cost=Object.keys({200:10,450:20,700:30}).find(k=>({200:10,450:20,700:30})[k]===tier);if(p.balance<+cost)return J({error:'Not enough points'},400);const code='PT-'+rnd(3).toUpperCase();await D.prepare("INSERT INTO store_coupons(code,percent,max_uses,used,expires_at) VALUES(?,?,1,0,date('now','+30 day'))").bind(code,tier).run();await D.prepare("INSERT INTO store_points_log(user_id,reason,ref,pts) VALUES(?,'redeem',?,?)").bind(u.id,code,-(+cost)).run();return J({code,percent:tier,...(await PT(c,u))})});
 // seller insights: views, conversion and the search words that led to each item
 r.get('/api/store/seller/insights',async c=>{const[u,e]=await need(c,'seller');if(e)return e;const D=c.env.DB,all=u.role==='admin',w=all?'':' AND i.seller_id=?1',pd="JOIN store_orders o ON o.id=oi.order_id AND o.status='paid'",q="SELECT i.id,(SELECT COALESCE(SUM(n),0) FROM store_item_views WHERE item_id=i.id AND day>=date('now','-30 day')) AS views,(SELECT COUNT(*) FROM store_order_items oi "+pd+" WHERE oi.item_id=i.id AND o.created_at>=datetime('now','-30 day')) AS sales FROM store_items i WHERE i.kind!='Plan'"+w+" LIMIT 200",rows=(await(all?D.prepare(q):D.prepare(q).bind(u.id)).all()).results;for(const x of rows)x.queries=(await D.prepare('SELECT q,n FROM store_search_hits WHERE item_id=? ORDER BY n DESC LIMIT 4').bind(x.id).all()).results;return J({items:rows})});

 r.get('/api/store/coupon/:code',async({env,params})=>{const c=await env.DB.prepare("SELECT percent FROM store_coupons WHERE code=? AND used<max_uses AND (expires_at IS NULL OR expires_at>=date('now'))").bind(String(params.code).toUpperCase()).first();return c?J({percent:c.percent}):J({error:'invalid'},404)});
